import * as d3 from 'd3';
import {
  drawArrow,
  drawCodeAnnotation,
  drawComponentLink,
  drawExplanation,
  drawLabel,
  drawMatrixBlock,
  Sel,
} from '../primitives';
import { StepInfo } from './index';
import { ComponentDef } from '../../components/types';
import { ComputationGraph } from '../../graph/types';

type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;

const W = 1200;
const CX = W / 2;

const COLORS = {
  input: { fill: '#e3f2fd', stroke: '#1976d2' },
  relu: { fill: '#e8f5e9', stroke: '#22c55e' },
  gelu: { fill: '#e3f2fd', stroke: '#1976d2' },
  silu: { fill: '#f3e5f5', stroke: '#7b1fa2' },
  swish: { fill: '#fff8e1', stroke: '#f59e0b' },
  output: { fill: '#e8f5e9', stroke: '#4caf50' },
  gradient: { fill: '#fce4ec', stroke: '#e91e63' },
  muted: 'var(--text-muted)' as string,
};

const BOX_H = 80;
const MAT_W = 260;
const MAT_H = 156;
const STEP_GAP = 360;
const BOX_TO_ROW = 260;
const SHAPE_GAP = 130;
const SIDE_OFF = 380;
const ARROW_MARGIN = 26;

const GRID_ROWS = 4;
const GRID_COLS = 7;
const CELL = 34;
const SMALL_CELL = 25;

interface AFStep extends StepInfo {}
type AFVariant = 'all' | 'relu' | 'gelu' | 'silu';

function lbl(
  g: Gsel, x: number, y: number, text: string,
  opts: { size?: number; weight?: string; color?: string; anchor?: 'start' | 'middle' | 'end'; font?: string } = {}
): void {
  drawLabel(g as Sel, x, y, text, opts);
}

function arrowH(
  g: Gsel, xFrom: number, xTo: number, y: number, color = '#94a3b8', margin = ARROW_MARGIN
): void {
  const dir = xTo >= xFrom ? 1 : -1;
  drawArrow(g as Sel, xFrom + dir * margin, y, xTo - dir * margin, y, { color });
}

function arrowV(
  g: Gsel, x: number, yFrom: number, yTo: number, color = '#94a3b8', margin = ARROW_MARGIN
): void {
  const dir = yTo >= yFrom ? 1 : -1;
  drawArrow(g as Sel, x, yFrom + dir * margin, x, yTo - dir * margin, { color });
}

function startGroup(g: Gsel, cls: string, step: number): Gsel {
  return g.append('g').attr('class', `step-node ${cls}`).attr('data-step', String(step));
}

function stepHeader(
  g: Gsel, cx: number, y: number, sn: number, title: string, formula: string,
  fill: string, stroke: string, width = W - 80
): number {
  const w = width;
  g.append('rect').attr('x', cx - w / 2).attr('y', y).attr('width', w).attr('height', BOX_H)
    .attr('rx', 8).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  g.append('circle').attr('cx', cx - w / 2 + 28).attr('cy', y + BOX_H / 2)
    .attr('r', 16).attr('fill', stroke);
  lbl(g, cx - w / 2 + 28, y + BOX_H / 2 + 1, String(sn), { size: 14, weight: '700', color: '#fff' });
  lbl(g, cx - w / 2 + 56, y + BOX_H / 2 - 7, title, { size: 15, weight: '600', color: 'var(--text)', anchor: 'start' });
  lbl(g, cx - w / 2 + 56, y + BOX_H / 2 + 14, formula, { size: 10, color: 'var(--text-muted)', font: 'monospace', anchor: 'start' });
  return y + BOX_H;
}

function shapeEq(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = Math.max(text.length * 7.5 + 56, 340);
  const h = 36;
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - h / 2).attr('width', w).attr('height', h)
    .attr('rx', 4).attr('fill', 'var(--surface)').attr('stroke', color).attr('stroke-width', 0.5).attr('opacity', 0.9);
  lbl(g, cx, cy + 1, text, { size: 11, color, font: 'monospace' });
}

function matrixBlock(
  g: Gsel, cx: number, cy: number, label: string, sub: string,
  fill: string, stroke: string, w = MAT_W, h = MAT_H,
  dimTop?: string, dimLeft?: string
): void {
  const top = dimTop ?? (sub.includes(',') ? sub.split(',')[1].trim().replace(/\]/, '') : '');
  const left = dimLeft ?? (sub.includes(',') ? sub.split(',')[0].trim().replace(/\[/, '') : '');
  drawMatrixBlock(g as Sel, cx - w / 2, cy - h / 2, {
    width: w, height: h, label, sublabel: sub, fill, stroke,
    cols: 8, rows: 6, dimTop: top, dimLeft: left,
  });
}

function opBox(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = text.length * 10 + 28;
  const h = 36;
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - h / 2).attr('width', w).attr('height', h)
    .attr('rx', 6).attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 1.5);
  lbl(g, cx, cy + 1, text, { size: 13, weight: '700', color });
}

function smallNote(g: Gsel, x: number, y: number, text: string, color: string, anchor: 'start' | 'middle' | 'end' = 'start'): void {
  lbl(g, x, y, text, { size: 10, color, anchor, font: 'monospace' });
}

function sampleNote(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = Math.max(text.length * 6.8 + 40, 200);
  const h = 24;
  g.append('rect')
    .attr('x', cx - w / 2).attr('y', cy - h / 2).attr('width', w).attr('height', h)
    .attr('rx', 4).attr('fill', 'var(--surface)').attr('stroke', color)
    .attr('stroke-width', 0.5).attr('opacity', 0.88);
  lbl(g, cx, cy + 1, text, { size: 10, color, font: 'monospace' });
}

function paramSummary(g: Gsel, cx: number, y: number, items: string[]): number {
  const w = W - 160;
  const h = 36;
  g.append('rect').attr('x', cx - w / 2).attr('y', y).attr('width', w).attr('height', h)
    .attr('rx', 6).attr('fill', 'var(--surface)').attr('stroke', 'var(--border)').attr('stroke-width', 0.5);
  const segW = w / items.length;
  items.forEach((item, i) => {
    lbl(g, cx - w / 2 + segW * (i + 0.5), y + h / 2 + 1, item, { size: 10, color: COLORS.muted, font: 'monospace' });
  });
  return y + h;
}

function makeStep(
  id: number, sl: string, l: string, f: string, ex: string,
  sg: string, c: string, fl: string, cl?: string[]
): AFStep {
  return { id, label: l, shortLabel: sl, formula: f, explanation: ex,
    code: { title: l, lines: cl || [`# ${f}`] }, svgGroup: sg, color: c, fill: fl };
}

function drawValueGrid(
  g: Gsel, cx: number, cy: number, rows: number, cols: number, cellSize: number,
  values: number[], transform: (v: number) => number, inColor: string, outColor: string
): void {
  const w = cols * cellSize;
  const h = rows * cellSize;
  const x0 = cx - w / 2;
  const y0 = cy - h / 2;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const idx = r * cols + c;
      const v = values[idx % values.length];
      const out = transform(v);
      const rx = x0 + c * cellSize;
      const ry = y0 + r * cellSize;
      const isZero = Math.abs(out) < 0.01;
      const isNeg = out < 0;
      g.append('rect').attr('x', rx).attr('y', ry).attr('width', cellSize - 1).attr('height', cellSize - 1)
        .attr('fill', isZero ? '#fef2f2' : isNeg ? '#fff7ed' : '#f0fdf4')
        .attr('stroke', '#e2e8f0').attr('stroke-width', 0.3);
      lbl(g, rx + cellSize / 2, ry + cellSize / 2, out.toFixed(1), {
        size: cellSize >= 24 ? 10 : 9, color: isZero ? '#f87171' : isNeg ? '#f97316' : outColor,
      });
    }
  }
  g.append('rect').attr('x', x0 - 1).attr('y', y0 - 1).attr('width', w + 2).attr('height', h + 2)
    .attr('fill', 'none').attr('stroke', inColor).attr('stroke-width', 1).attr('rx', 2);
}

function drawInputGrid(
  g: Gsel, cx: number, cy: number, rows: number, cols: number, cellSize: number,
  values: number[], color: string
): void {
  const w = cols * cellSize;
  const h = rows * cellSize;
  const x0 = cx - w / 2;
  const y0 = cy - h / 2;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const idx = r * cols + c;
      const v = values[idx % values.length];
      const rx = x0 + c * cellSize;
      const ry = y0 + r * cellSize;
      const isNeg = v < 0;
      g.append('rect').attr('x', rx).attr('y', ry).attr('width', cellSize - 1).attr('height', cellSize - 1)
        .attr('fill', isNeg ? '#fff3e0' : '#e3f2fd').attr('stroke', '#e2e8f0').attr('stroke-width', 0.3);
      lbl(g, rx + cellSize / 2, ry + cellSize / 2, v.toFixed(1), {
        size: cellSize >= 24 ? 10 : 9, color: isNeg ? '#f97316' : color,
      });
    }
  }
  g.append('rect').attr('x', x0 - 1).attr('y', y0 - 1).attr('width', w + 2).attr('height', h + 2)
    .attr('fill', 'none').attr('stroke', color).attr('stroke-width', 1).attr('rx', 2);
}

const SAMPLE_VALUES = [-2.0, -1.0, -0.5, 0.0, 0.5, 1.0, 1.5, 2.0, -1.5, -0.3, 0.3, 0.8, -0.8, 1.2, -1.2, 0.6];

function reluFn(x: number): number { return Math.max(0, x); }
function geluFn(x: number): number { return x * 0.5 * (1 + Math.tanh(Math.sqrt(2 / Math.PI) * (x + 0.044715 * x * x * x))); }
function siluFn(x: number): number { return x / (1 + Math.exp(-x)); }
function swishFn(x: number): number { return x / (1 + Math.exp(-0.5 * x)); }
function sigmoidFn(x: number): number { return 1 / (1 + Math.exp(-x)); }
function cdfFn(x: number): number { return 0.5 * (1 + Math.tanh(Math.sqrt(2 / Math.PI) * (x + 0.044715 * x * x * x))); }

// ═══════════════════════════════════════════════════════════════════════════════
// All (comparison) variant
// ═══════════════════════════════════════════════════════════════════════════════

function renderAll(
  g: Gsel, yStart: number, seqLen: number, dModel: number
): { steps: AFStep[]; y: number } {
  const steps: AFStep[] = [];
  let y = yStart;

  // Step 1: Input
  {
    const stepId = 1;
    const gs = startGroup(g, 'step-input', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Input Activations',
      `x [${seqLen}, ${dModel}]`, COLORS.input.fill, COLORS.input.stroke);
    const rowY = hBottom + BOX_TO_ROW;
    const gridW = GRID_COLS * CELL;
    const gridH = GRID_ROWS * CELL;

    drawInputGrid(gs, CX, rowY, GRID_ROWS, GRID_COLS, CELL, SAMPLE_VALUES, COLORS.input.stroke);
    lbl(gs, CX, rowY - gridH / 2 - 20, 'x', { size: 14, weight: '700', color: COLORS.input.stroke });
    smallNote(gs, CX + gridW / 2 + 16, rowY - 12, 'blue = positive', COLORS.input.stroke);
    smallNote(gs, CX + gridW / 2 + 16, rowY + 8, 'orange = negative', '#f97316');

    shapeEq(gs, CX, rowY + gridH / 2 + 36,
      `x  [${seqLen}, ${dModel}]`, COLORS.input.stroke);
    sampleNote(gs, CX, rowY + gridH / 2 + 36 + 30,
      'same input applied to all 4 activations', COLORS.input.stroke);

    steps.push(makeStep(stepId, 'Input', 'Input Activations',
      `x [${seqLen}, ${dModel}]`,
      'Input activation matrix. We compare how each activation function transforms the same input.',
      'step-input', COLORS.input.stroke, COLORS.input.fill,
      [`x = torch.randn(${seqLen}, ${dModel})`]));
    y = rowY + gridH / 2 + 36 + 30 + 24 + SHAPE_GAP + STEP_GAP;
  }

  // Step 2: Side-by-side comparison (2x2 grid)
  {
    const stepId = 2;
    const gs = startGroup(g, 'step-compare', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Activation Comparison',
      'ReLU vs GELU vs SiLU vs Swish', COLORS.relu.fill, COLORS.relu.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const activations = [
      { name: 'ReLU', fn: reluFn, color: COLORS.relu, formula: 'max(0, x)', cx: CX - 260, cy: rowY - 90 },
      { name: 'GELU', fn: geluFn, color: COLORS.gelu, formula: 'x · Φ(x)', cx: CX + 260, cy: rowY - 90 },
      { name: 'SiLU', fn: siluFn, color: COLORS.silu, formula: 'x · σ(x)', cx: CX - 260, cy: rowY + 110 },
      { name: 'Swish', fn: swishFn, color: COLORS.swish, formula: 'x · σ(βx)', cx: CX + 260, cy: rowY + 110 },
    ];

    const boxW = 460;
    const boxH = 180;
    const gridCols = 6;
    const gridRows = 3;
    const gCell = 22;

    for (const act of activations) {
      gs.append('rect').attr('x', act.cx - boxW / 2).attr('y', act.cy - boxH / 2)
        .attr('width', boxW).attr('height', boxH)
        .attr('rx', 8).attr('fill', 'var(--surface)').attr('stroke', act.color.stroke)
        .attr('stroke-width', 1.5).attr('opacity', 0.95);

      lbl(gs, act.cx - boxW / 2 + 18, act.cy - boxH / 2 + 22, act.name, {
        size: 13, weight: '700', color: act.color.stroke, anchor: 'start',
      });
      lbl(gs, act.cx - boxW / 2 + 18, act.cy - boxH / 2 + 40, act.formula, {
        size: 10, color: COLORS.muted, font: 'monospace', anchor: 'start',
      });

      drawValueGrid(gs, act.cx, act.cy + 20, gridRows, gridCols, gCell,
        SAMPLE_VALUES, act.fn, act.color.stroke, act.color.stroke);
    }

    shapeEq(gs, CX, rowY + 210,
      'each activation transforms the same input differently', COLORS.relu.stroke);

    steps.push(makeStep(stepId, 'Compare', 'Activation Comparison',
      'ReLU vs GELU vs SiLU vs Swish',
      'ReLU is sparse (zeros negatives). GELU smoothly approximates ReLU. SiLU/Swish use sigmoid gating.',
      'step-compare', COLORS.relu.stroke, COLORS.relu.fill,
      [`relu = torch.relu(x)`, `gelu = F.gelu(x)`, `silu = F.silu(x)`]));
    y = rowY + 210 + SHAPE_GAP + STEP_GAP;
  }

  // Step 3: Gradient comparison
  {
    const stepId = 3;
    const gs = startGroup(g, 'step-gradient', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Gradient Comparison',
      'd/dx for each activation', COLORS.gradient.fill, COLORS.gradient.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const grads = [
      { name: "ReLU'", desc: '0 or 1', detail: 'dying neurons', cx: CX - 360, color: COLORS.relu },
      { name: "GELU'", desc: 'smooth', detail: 'always > 0', cx: CX - 120, color: COLORS.gelu },
      { name: "SiLU'", desc: 'smooth', detail: 'always > 0', cx: CX + 120, color: COLORS.silu },
      { name: "Swish'", desc: 'smooth', detail: 'always > 0', cx: CX + 360, color: COLORS.swish },
    ];

    for (const gr of grads) {
      const boxW = 200;
      const boxH = 120;
      gs.append('rect').attr('x', gr.cx - boxW / 2).attr('y', rowY - boxH / 2)
        .attr('width', boxW).attr('height', boxH)
        .attr('rx', 8).attr('fill', gr.color.fill).attr('stroke', gr.color.stroke)
        .attr('stroke-width', 1.5);
      lbl(gs, gr.cx, rowY - 20, gr.name, { size: 13, weight: '700', color: gr.color.stroke });
      lbl(gs, gr.cx, rowY + 4, gr.desc, { size: 11, color: 'var(--text)', font: 'monospace' });
      lbl(gs, gr.cx, rowY + 28, gr.detail, { size: 10, color: COLORS.muted });
    }

    shapeEq(gs, CX, rowY + 80,
      "ReLU: dying neuron problem  |  GELU/SiLU: smooth gradients everywhere", COLORS.gradient.stroke);

    steps.push(makeStep(stepId, 'Gradient', 'Gradient Comparison',
      'd/dx comparison',
      'ReLU has binary gradients (0 or 1) causing dying neurons. GELU and SiLU have smooth gradients everywhere.',
      'step-gradient', COLORS.gradient.stroke, COLORS.gradient.fill,
      [`# ReLU: grad = (x > 0).float()`, `# GELU/SiLU: smooth gradients everywhere`]));
    y = rowY + 80 + SHAPE_GAP + STEP_GAP;
  }

  // Step 4: Usage summary
  {
    const stepId = 4;
    const gs = startGroup(g, 'step-output', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Usage Summary',
      'which activation to use?', COLORS.output.fill, COLORS.output.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const usages = [
      { name: 'ReLU', where: 'CNNs, fast inference', cx: CX - 360, color: COLORS.relu },
      { name: 'GELU', where: 'BERT, GPT, ViT', cx: CX - 120, color: COLORS.gelu },
      { name: 'SiLU', where: 'LLaMA, EfficientNet', cx: CX + 120, color: COLORS.silu },
      { name: 'Swish', where: 'NAS-found, EfficientNet', cx: CX + 360, color: COLORS.swish },
    ];

    for (const u of usages) {
      const boxW = 200;
      const boxH = 90;
      gs.append('rect').attr('x', u.cx - boxW / 2).attr('y', rowY - boxH / 2)
        .attr('width', boxW).attr('height', boxH)
        .attr('rx', 8).attr('fill', u.color.fill).attr('stroke', u.color.stroke)
        .attr('stroke-width', 1.5);
      lbl(gs, u.cx, rowY - 12, u.name, { size: 13, weight: '700', color: u.color.stroke });
      lbl(gs, u.cx, rowY + 16, u.where, { size: 10, color: COLORS.muted });
    }

    shapeEq(gs, CX, rowY + 66,
      `output shape: [${seqLen}, ${dModel}]  (same as input)`, COLORS.output.stroke);

    steps.push(makeStep(stepId, 'Summary', 'Usage Summary',
      'activation selection guide',
      'ReLU for speed/sparsity. GELU for transformers. SiLU for modern LLMs. Swish for NAS-discovered architectures.',
      'step-output', COLORS.output.stroke, COLORS.output.fill,
      [`# Choose based on model architecture and training stability needs`]));
    y = rowY + 66 + SHAPE_GAP;
  }

  return { steps, y };
}

// ═══════════════════════════════════════════════════════════════════════════════
// ReLU variant
// ═══════════════════════════════════════════════════════════════════════════════

function renderReLU(
  g: Gsel, yStart: number, seqLen: number, dModel: number
): { steps: AFStep[]; y: number } {
  const steps: AFStep[] = [];
  let y = yStart;

  // Step 1: Input
  {
    const stepId = 1;
    const gs = startGroup(g, 'step-input', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Input Activations',
      `x [${seqLen}, ${dModel}]`, COLORS.input.fill, COLORS.input.stroke);
    const rowY = hBottom + BOX_TO_ROW;
    const gridW = GRID_COLS * CELL;
    const gridH = GRID_ROWS * CELL;

    drawInputGrid(gs, CX, rowY, GRID_ROWS, GRID_COLS, CELL, SAMPLE_VALUES, COLORS.input.stroke);
    lbl(gs, CX, rowY - gridH / 2 - 20, 'x', { size: 14, weight: '700', color: COLORS.input.stroke });
    smallNote(gs, CX + gridW / 2 + 16, rowY - 12, 'blue = positive', COLORS.input.stroke);
    smallNote(gs, CX + gridW / 2 + 16, rowY + 8, 'orange = negative (will be zeroed)', '#f97316');

    shapeEq(gs, CX, rowY + gridH / 2 + 36,
      `x  [${seqLen}, ${dModel}]`, COLORS.input.stroke);
    sampleNote(gs, CX, rowY + gridH / 2 + 36 + 30,
      'sample values from [-2, 2] range', COLORS.input.stroke);

    steps.push(makeStep(stepId, 'Input', 'Input Activations',
      `x [${seqLen}, ${dModel}]`,
      'Input activation matrix. Negative values (orange) will be zeroed by ReLU.',
      'step-input', COLORS.input.stroke, COLORS.input.fill,
      [`x = torch.randn(${seqLen}, ${dModel})`]));
    y = rowY + gridH / 2 + 36 + 30 + 24 + SHAPE_GAP + STEP_GAP;
  }

  // Step 2: Apply max(0, x)
  {
    const stepId = 2;
    const gs = startGroup(g, 'step-apply', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Apply max(0, x)',
      'ReLU(x) = max(0, x)', COLORS.relu.fill, COLORS.relu.stroke);
    const rowY = hBottom + BOX_TO_ROW;
    const sCell = SMALL_CELL;
    const gridW = GRID_COLS * sCell;
    const gridH = GRID_ROWS * sCell;

    drawInputGrid(gs, CX - SIDE_OFF, rowY, GRID_ROWS, GRID_COLS, sCell, SAMPLE_VALUES, COLORS.input.stroke);
    lbl(gs, CX - SIDE_OFF, rowY - gridH / 2 - 18, 'x', { size: 12, weight: '700', color: COLORS.input.stroke });

    opBox(gs, CX, rowY, 'max(0, ·)', COLORS.relu.stroke);

    drawValueGrid(gs, CX + SIDE_OFF, rowY, GRID_ROWS, GRID_COLS, sCell, SAMPLE_VALUES, reluFn, COLORS.relu.stroke, COLORS.relu.stroke);
    lbl(gs, CX + SIDE_OFF, rowY - gridH / 2 - 18, 'ReLU(x)', { size: 12, weight: '700', color: COLORS.relu.stroke });

    const leftGridRight = CX - SIDE_OFF + gridW / 2;
    const rightGridLeft = CX + SIDE_OFF - gridW / 2;
    arrowH(gs, leftGridRight, CX - 60, rowY, COLORS.input.stroke);
    arrowH(gs, CX + 60, rightGridLeft, rowY, COLORS.relu.stroke);

    shapeEq(gs, CX, rowY + gridH / 2 + 36,
      `ReLU(x) = max(0, x)  [${seqLen}, ${dModel}]`, COLORS.relu.stroke);
    sampleNote(gs, CX, rowY + gridH / 2 + 36 + 30,
      'negative values → 0  |  positive values → unchanged', COLORS.relu.stroke);

    steps.push(makeStep(stepId, 'Apply', 'Apply max(0, x)',
      'ReLU(x) = max(0, x)',
      'Element-wise: if x < 0 output 0, else output x. Creates sparse activations.',
      'step-apply', COLORS.relu.stroke, COLORS.relu.fill,
      [`out = torch.relu(x)  # or: out = torch.clamp(x, min=0)`]));
    y = rowY + gridH / 2 + 36 + 30 + 24 + SHAPE_GAP + STEP_GAP;
  }

  // Step 3: Sparsity analysis
  {
    const stepId = 3;
    const gs = startGroup(g, 'step-sparsity', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Sparsity & Dead Neurons',
      'P(ReLU=0) depends on input distribution', COLORS.gradient.fill, COLORS.gradient.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const activeX = CX - 220;
    const deadX = CX + 220;
    const caseH = 160;
    const caseW = 360;

    gs.append('rect').attr('x', activeX - caseW / 2).attr('y', rowY - caseH / 2)
      .attr('width', caseW).attr('height', caseH)
      .attr('rx', 8).attr('fill', '#f0fdf4').attr('stroke', COLORS.relu.stroke).attr('stroke-width', 1.5);
    lbl(gs, activeX, rowY - caseH / 2 + 24, 'Active neuron (x > 0)', { size: 13, weight: '700', color: COLORS.relu.stroke });
    lbl(gs, activeX, rowY - 8, 'output = x,  grad = 1', { size: 11, color: 'var(--text)', font: 'monospace' });
    lbl(gs, activeX, rowY + 18, 'gradient flows normally', { size: 10, color: COLORS.muted });
    lbl(gs, activeX, rowY + caseH / 2 - 20, 'healthy neuron', { size: 10, color: COLORS.relu.stroke });

    gs.append('rect').attr('x', deadX - caseW / 2).attr('y', rowY - caseH / 2)
      .attr('width', caseW).attr('height', caseH)
      .attr('rx', 8).attr('fill', '#fef2f2').attr('stroke', '#f87171').attr('stroke-width', 1.5);
    lbl(gs, deadX, rowY - caseH / 2 + 24, 'Dead neuron (x ≤ 0)', { size: 13, weight: '700', color: '#ef4444' });
    lbl(gs, deadX, rowY - 8, 'output = 0,  grad = 0', { size: 11, color: 'var(--text)', font: 'monospace' });
    lbl(gs, deadX, rowY + 18, 'no gradient → never recovers', { size: 10, color: COLORS.muted });
    lbl(gs, deadX, rowY + caseH / 2 - 20, '"dying ReLU" problem', { size: 10, color: '#ef4444' });

    shapeEq(gs, CX, rowY + caseH / 2 + 36,
      'dying ReLU: large learning rate → permanent zero', COLORS.gradient.stroke);

    steps.push(makeStep(stepId, 'Sparsity', 'Sparsity & Dead Neurons',
      'dying ReLU problem',
      'When inputs are always negative, the neuron outputs 0 forever. Large learning rates can push weights so the neuron never activates again.',
      'step-sparsity', COLORS.gradient.stroke, COLORS.gradient.fill,
      [`# Fix: use LeakyReLU, or lower learning rate`]));
    y = rowY + caseH / 2 + 36 + SHAPE_GAP + STEP_GAP;
  }

  // Step 4: Output
  {
    const stepId = 4;
    const gs = startGroup(g, 'step-output', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Output',
      `ReLU(x) [${seqLen}, ${dModel}]`, COLORS.output.fill, COLORS.output.stroke);
    const rowY = hBottom + BOX_TO_ROW;
    const gridW = GRID_COLS * CELL;
    const gridH = GRID_ROWS * CELL;

    drawValueGrid(gs, CX, rowY, GRID_ROWS, GRID_COLS, CELL, SAMPLE_VALUES, reluFn, COLORS.output.stroke, COLORS.output.stroke);
    lbl(gs, CX, rowY - gridH / 2 - 20, 'ReLU(x)', { size: 14, weight: '700', color: COLORS.output.stroke });
    smallNote(gs, CX + gridW / 2 + 16, rowY - 12, 'green = positive', COLORS.output.stroke);
    smallNote(gs, CX + gridW / 2 + 16, rowY + 8, 'red = zeroed', '#f87171');

    shapeEq(gs, CX, rowY + gridH / 2 + 36,
      `ReLU(x)  [${seqLen}, ${dModel}]`, COLORS.output.stroke);
    sampleNote(gs, CX, rowY + gridH / 2 + 36 + 30,
      'sparse output → efficient computation', COLORS.output.stroke);

    steps.push(makeStep(stepId, 'Output', 'Output',
      `ReLU(x) [${seqLen}, ${dModel}]`,
      'Output has the same shape as input. Many values are zero (sparse), which is computationally efficient.',
      'step-output', COLORS.output.stroke, COLORS.output.fill,
      [`# ReLU: fast, sparse, but watch for dying neurons`]));
    y = rowY + gridH / 2 + 36 + 30 + 24 + SHAPE_GAP;
  }

  return { steps, y };
}

// ═══════════════════════════════════════════════════════════════════════════════
// GELU variant
// ═══════════════════════════════════════════════════════════════════════════════

function renderGELU(
  g: Gsel, yStart: number, seqLen: number, dModel: number
): { steps: AFStep[]; y: number } {
  const steps: AFStep[] = [];
  let y = yStart;

  // Step 1: Input
  {
    const stepId = 1;
    const gs = startGroup(g, 'step-input', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Input Activations',
      `x [${seqLen}, ${dModel}]`, COLORS.input.fill, COLORS.input.stroke);
    const rowY = hBottom + BOX_TO_ROW;
    const gridW = GRID_COLS * CELL;
    const gridH = GRID_ROWS * CELL;

    drawInputGrid(gs, CX, rowY, GRID_ROWS, GRID_COLS, CELL, SAMPLE_VALUES, COLORS.input.stroke);
    lbl(gs, CX, rowY - gridH / 2 - 20, 'x', { size: 14, weight: '700', color: COLORS.input.stroke });
    smallNote(gs, CX + gridW / 2 + 16, rowY - 12, 'blue = positive', COLORS.input.stroke);
    smallNote(gs, CX + gridW / 2 + 16, rowY + 8, 'orange = negative', '#f97316');

    shapeEq(gs, CX, rowY + gridH / 2 + 36,
      `x  [${seqLen}, ${dModel}]`, COLORS.input.stroke);

    steps.push(makeStep(stepId, 'Input', 'Input Activations',
      `x [${seqLen}, ${dModel}]`,
      'Input activation matrix. GELU will smoothly gate these values.',
      'step-input', COLORS.input.stroke, COLORS.input.fill,
      [`x = torch.randn(${seqLen}, ${dModel})`]));
    y = rowY + gridH / 2 + 36 + SHAPE_GAP + STEP_GAP;
  }

  // Step 2: Compute Φ(x)
  {
    const stepId = 2;
    const gs = startGroup(g, 'step-phi', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Compute Φ(x) — Gaussian CDF',
      'Φ(x) ≈ 0.5·(1 + tanh(√(2/π)·(x + 0.044715·x³)))', COLORS.gelu.fill, COLORS.gelu.stroke);
    const rowY = hBottom + BOX_TO_ROW;
    const sCell = SMALL_CELL;
    const gridW = GRID_COLS * sCell;
    const gridH = GRID_ROWS * sCell;

    drawInputGrid(gs, CX - SIDE_OFF, rowY, GRID_ROWS, GRID_COLS, sCell, SAMPLE_VALUES, COLORS.input.stroke);
    lbl(gs, CX - SIDE_OFF, rowY - gridH / 2 - 18, 'x', { size: 12, weight: '700', color: COLORS.input.stroke });

    opBox(gs, CX, rowY, 'Φ(·)', COLORS.gelu.stroke);

    drawValueGrid(gs, CX + SIDE_OFF, rowY, GRID_ROWS, GRID_COLS, sCell, SAMPLE_VALUES, cdfFn, COLORS.gelu.stroke, COLORS.gelu.stroke);
    lbl(gs, CX + SIDE_OFF, rowY - gridH / 2 - 18, 'Φ(x)', { size: 12, weight: '700', color: COLORS.gelu.stroke });

    const leftGridRight = CX - SIDE_OFF + gridW / 2;
    const rightGridLeft = CX + SIDE_OFF - gridW / 2;
    arrowH(gs, leftGridRight, CX - 40, rowY, COLORS.input.stroke);
    arrowH(gs, CX + 40, rightGridLeft, rowY, COLORS.gelu.stroke);

    shapeEq(gs, CX, rowY + gridH / 2 + 36,
      'Φ(x) ∈ [0, 1] — smooth gating function', COLORS.gelu.stroke);
    sampleNote(gs, CX, rowY + gridH / 2 + 36 + 30,
      'Φ(-2) ≈ 0.02,  Φ(0) = 0.5,  Φ(2) ≈ 0.98', COLORS.gelu.stroke);

    steps.push(makeStep(stepId, 'CDF', 'Compute Φ(x)',
      'Gaussian CDF approximation',
      'The CDF of the standard normal distribution. Uses tanh approximation for speed. Φ(x) acts as a soft gate: near 0 for large negative x, near 1 for large positive x.',
      'step-phi', COLORS.gelu.stroke, COLORS.gelu.fill,
      [`phi = 0.5 * (1 + torch.tanh(math.sqrt(2/math.pi) * (x + 0.044715 * x**3)))`]));
    y = rowY + gridH / 2 + 36 + 30 + 24 + SHAPE_GAP + STEP_GAP;
  }

  // Step 3: Multiply x * Φ(x)
  {
    const stepId = 3;
    const gs = startGroup(g, 'step-mul', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Multiply x · Φ(x)',
      'GELU(x) = x · Φ(x)', COLORS.gelu.fill, COLORS.gelu.stroke);
    const rowY = hBottom + BOX_TO_ROW;
    const sCell = SMALL_CELL;
    const gridW = GRID_COLS * sCell;
    const gridH = GRID_ROWS * sCell;

    matrixBlock(gs, CX - SIDE_OFF, rowY, 'x', `[${seqLen}, ${dModel}]`, COLORS.input.fill, COLORS.input.stroke, MAT_W * 0.8, MAT_H * 0.8);

    opBox(gs, CX, rowY, '⊙', COLORS.gelu.stroke);

    drawValueGrid(gs, CX + SIDE_OFF, rowY, GRID_ROWS, GRID_COLS, sCell, SAMPLE_VALUES, geluFn, COLORS.gelu.stroke, COLORS.gelu.stroke);
    lbl(gs, CX + SIDE_OFF, rowY - gridH / 2 - 18, 'GELU(x)', { size: 12, weight: '700', color: COLORS.gelu.stroke });

    const matRight = CX - SIDE_OFF + (MAT_W * 0.8) / 2;
    const rightGridLeft = CX + SIDE_OFF - gridW / 2;
    arrowH(gs, matRight, CX - 24, rowY, COLORS.input.stroke);
    arrowH(gs, CX + 24, rightGridLeft, rowY, COLORS.gelu.stroke);

    const phiY = rowY - 110;
    const phiW = 140;
    const phiH = 56;
    gs.append('rect').attr('x', CX - phiW / 2).attr('y', phiY - phiH / 2)
      .attr('width', phiW).attr('height', phiH)
      .attr('rx', 6).attr('fill', COLORS.gelu.fill).attr('stroke', COLORS.gelu.stroke).attr('stroke-width', 1.5);
    lbl(gs, CX, phiY - 8, 'Φ(x)', { size: 12, weight: '700', color: COLORS.gelu.stroke });
    lbl(gs, CX, phiY + 12, '∈ [0, 1]', { size: 10, color: COLORS.muted, font: 'monospace' });
    arrowV(gs, CX, phiY + phiH / 2, rowY - 20, COLORS.gelu.stroke);

    shapeEq(gs, CX, rowY + gridH / 2 + 36,
      `GELU(x) = x · Φ(x)  [${seqLen}, ${dModel}]`, COLORS.gelu.stroke);
    sampleNote(gs, CX, rowY + gridH / 2 + 36 + 30,
      'GELU(-1) ≈ -0.16 (not zero!),  GELU(1) ≈ 0.84', COLORS.gelu.stroke);

    steps.push(makeStep(stepId, 'Multiply', 'Multiply x · Φ(x)',
      'GELU(x) = x · Φ(x)',
      'Element-wise multiplication. Unlike ReLU, negative values are not fully zeroed — they are softly gated.',
      'step-mul', COLORS.gelu.stroke, COLORS.gelu.fill,
      [`gelu = x * phi`]));
    y = rowY + gridH / 2 + 36 + 30 + 24 + SHAPE_GAP + STEP_GAP;
  }

  // Step 4: Output
  {
    const stepId = 4;
    const gs = startGroup(g, 'step-output', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Output',
      `GELU(x) [${seqLen}, ${dModel}]`, COLORS.output.fill, COLORS.output.stroke);
    const rowY = hBottom + BOX_TO_ROW;
    const gridW = GRID_COLS * CELL;
    const gridH = GRID_ROWS * CELL;

    drawValueGrid(gs, CX, rowY, GRID_ROWS, GRID_COLS, CELL, SAMPLE_VALUES, geluFn, COLORS.output.stroke, COLORS.output.stroke);
    lbl(gs, CX, rowY - gridH / 2 - 20, 'GELU(x)', { size: 14, weight: '700', color: COLORS.output.stroke });
    smallNote(gs, CX + gridW / 2 + 16, rowY - 12, 'green = positive', COLORS.output.stroke);
    smallNote(gs, CX + gridW / 2 + 16, rowY + 8, 'orange = negative (soft)', '#f97316');

    shapeEq(gs, CX, rowY + gridH / 2 + 36,
      `GELU(x)  [${seqLen}, ${dModel}]`, COLORS.output.stroke);
    sampleNote(gs, CX, rowY + gridH / 2 + 36 + 30,
      'used in BERT, GPT, ViT — smooth gradients everywhere', COLORS.output.stroke);

    steps.push(makeStep(stepId, 'Output', 'Output',
      `GELU(x) [${seqLen}, ${dModel}]`,
      'Output has the same shape. GELU provides smooth gradients, avoiding the dying neuron problem of ReLU.',
      'step-output', COLORS.output.stroke, COLORS.output.fill,
      [`# GELU: smooth, non-zero for negatives, used in transformers`]));
    y = rowY + gridH / 2 + 36 + 30 + 24 + SHAPE_GAP;
  }

  return { steps, y };
}

// ═══════════════════════════════════════════════════════════════════════════════
// SiLU/Swish variant
// ═══════════════════════════════════════════════════════════════════════════════

function renderSiLU(
  g: Gsel, yStart: number, seqLen: number, dModel: number
): { steps: AFStep[]; y: number } {
  const steps: AFStep[] = [];
  let y = yStart;

  // Step 1: Input
  {
    const stepId = 1;
    const gs = startGroup(g, 'step-input', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Input Activations',
      `x [${seqLen}, ${dModel}]`, COLORS.input.fill, COLORS.input.stroke);
    const rowY = hBottom + BOX_TO_ROW;
    const gridW = GRID_COLS * CELL;
    const gridH = GRID_ROWS * CELL;

    drawInputGrid(gs, CX, rowY, GRID_ROWS, GRID_COLS, CELL, SAMPLE_VALUES, COLORS.input.stroke);
    lbl(gs, CX, rowY - gridH / 2 - 20, 'x', { size: 14, weight: '700', color: COLORS.input.stroke });
    smallNote(gs, CX + gridW / 2 + 16, rowY - 12, 'blue = positive', COLORS.input.stroke);
    smallNote(gs, CX + gridW / 2 + 16, rowY + 8, 'orange = negative', '#f97316');

    shapeEq(gs, CX, rowY + gridH / 2 + 36,
      `x  [${seqLen}, ${dModel}]`, COLORS.input.stroke);

    steps.push(makeStep(stepId, 'Input', 'Input Activations',
      `x [${seqLen}, ${dModel}]`,
      'Input activation matrix. SiLU will apply sigmoid gating.',
      'step-input', COLORS.input.stroke, COLORS.input.fill,
      [`x = torch.randn(${seqLen}, ${dModel})`]));
    y = rowY + gridH / 2 + 36 + SHAPE_GAP + STEP_GAP;
  }

  // Step 2: Compute σ(x)
  {
    const stepId = 2;
    const gs = startGroup(g, 'step-sigmoid', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Compute σ(x) — Sigmoid',
      'σ(x) = 1 / (1 + e⁻ˣ)', COLORS.silu.fill, COLORS.silu.stroke);
    const rowY = hBottom + BOX_TO_ROW;
    const sCell = SMALL_CELL;
    const gridW = GRID_COLS * sCell;
    const gridH = GRID_ROWS * sCell;

    drawInputGrid(gs, CX - SIDE_OFF, rowY, GRID_ROWS, GRID_COLS, sCell, SAMPLE_VALUES, COLORS.input.stroke);
    lbl(gs, CX - SIDE_OFF, rowY - gridH / 2 - 18, 'x', { size: 12, weight: '700', color: COLORS.input.stroke });

    opBox(gs, CX, rowY, 'σ(·)', COLORS.silu.stroke);

    drawValueGrid(gs, CX + SIDE_OFF, rowY, GRID_ROWS, GRID_COLS, sCell, SAMPLE_VALUES, sigmoidFn, COLORS.silu.stroke, COLORS.silu.stroke);
    lbl(gs, CX + SIDE_OFF, rowY - gridH / 2 - 18, 'σ(x)', { size: 12, weight: '700', color: COLORS.silu.stroke });

    const leftGridRight = CX - SIDE_OFF + gridW / 2;
    const rightGridLeft = CX + SIDE_OFF - gridW / 2;
    arrowH(gs, leftGridRight, CX - 40, rowY, COLORS.input.stroke);
    arrowH(gs, CX + 40, rightGridLeft, rowY, COLORS.silu.stroke);

    shapeEq(gs, CX, rowY + gridH / 2 + 36,
      'σ(x) ∈ (0, 1) — sigmoid gate', COLORS.silu.stroke);
    sampleNote(gs, CX, rowY + gridH / 2 + 36 + 30,
      'σ(-2) ≈ 0.12,  σ(0) = 0.5,  σ(2) ≈ 0.88', COLORS.silu.stroke);

    steps.push(makeStep(stepId, 'Sigmoid', 'Compute σ(x)',
      'σ(x) = 1/(1+e⁻ˣ)',
      "Sigmoid squashes values to (0, 1). Acts as a learnable gate — unlike GELU's CDF, it's asymmetric around 0.",
      'step-sigmoid', COLORS.silu.stroke, COLORS.silu.fill,
      [`sig = torch.sigmoid(x)`]));
    y = rowY + gridH / 2 + 36 + 30 + 24 + SHAPE_GAP + STEP_GAP;
  }

  // Step 3: Multiply x * σ(x)
  {
    const stepId = 3;
    const gs = startGroup(g, 'step-mul', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Multiply x · σ(x)',
      'SiLU(x) = x · σ(x)', COLORS.silu.fill, COLORS.silu.stroke);
    const rowY = hBottom + BOX_TO_ROW;
    const sCell = SMALL_CELL;
    const gridW = GRID_COLS * sCell;
    const gridH = GRID_ROWS * sCell;

    matrixBlock(gs, CX - SIDE_OFF, rowY, 'x', `[${seqLen}, ${dModel}]`, COLORS.input.fill, COLORS.input.stroke, MAT_W * 0.8, MAT_H * 0.8);

    opBox(gs, CX, rowY, '⊙', COLORS.silu.stroke);

    drawValueGrid(gs, CX + SIDE_OFF, rowY, GRID_ROWS, GRID_COLS, sCell, SAMPLE_VALUES, siluFn, COLORS.silu.stroke, COLORS.silu.stroke);
    lbl(gs, CX + SIDE_OFF, rowY - gridH / 2 - 18, 'SiLU(x)', { size: 12, weight: '700', color: COLORS.silu.stroke });

    const matRight = CX - SIDE_OFF + (MAT_W * 0.8) / 2;
    const rightGridLeft = CX + SIDE_OFF - gridW / 2;
    arrowH(gs, matRight, CX - 24, rowY, COLORS.input.stroke);
    arrowH(gs, CX + 24, rightGridLeft, rowY, COLORS.silu.stroke);

    const sigY = rowY - 110;
    const sigW = 140;
    const sigH = 56;
    gs.append('rect').attr('x', CX - sigW / 2).attr('y', sigY - sigH / 2)
      .attr('width', sigW).attr('height', sigH)
      .attr('rx', 6).attr('fill', COLORS.silu.fill).attr('stroke', COLORS.silu.stroke).attr('stroke-width', 1.5);
    lbl(gs, CX, sigY - 8, 'σ(x)', { size: 12, weight: '700', color: COLORS.silu.stroke });
    lbl(gs, CX, sigY + 12, '∈ (0, 1)', { size: 10, color: COLORS.muted, font: 'monospace' });
    arrowV(gs, CX, sigY + sigH / 2, rowY - 20, COLORS.silu.stroke);

    shapeEq(gs, CX, rowY + gridH / 2 + 36,
      `SiLU(x) = x · σ(x)  [${seqLen}, ${dModel}]`, COLORS.silu.stroke);
    sampleNote(gs, CX, rowY + gridH / 2 + 36 + 30,
      'SiLU(-1) ≈ -0.27,  SiLU(0) = 0,  SiLU(1) ≈ 0.73', COLORS.silu.stroke);

    steps.push(makeStep(stepId, 'Multiply', 'Multiply x · σ(x)',
      'SiLU(x) = x · σ(x)',
      'The sigmoid gate modulates the input. Negative values are attenuated but not zeroed (unlike ReLU). SiLU is also called Swish when β=1.',
      'step-mul', COLORS.silu.stroke, COLORS.silu.fill,
      [`silu = x * torch.sigmoid(x)`]));
    y = rowY + gridH / 2 + 36 + 30 + 24 + SHAPE_GAP + STEP_GAP;
  }

  // Step 4: Output
  {
    const stepId = 4;
    const gs = startGroup(g, 'step-output', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Output',
      `SiLU(x) [${seqLen}, ${dModel}]`, COLORS.output.fill, COLORS.output.stroke);
    const rowY = hBottom + BOX_TO_ROW;
    const gridW = GRID_COLS * CELL;
    const gridH = GRID_ROWS * CELL;

    drawValueGrid(gs, CX, rowY, GRID_ROWS, GRID_COLS, CELL, SAMPLE_VALUES, siluFn, COLORS.output.stroke, COLORS.output.stroke);
    lbl(gs, CX, rowY - gridH / 2 - 20, 'SiLU(x)', { size: 14, weight: '700', color: COLORS.output.stroke });
    smallNote(gs, CX + gridW / 2 + 16, rowY - 12, 'green = positive', COLORS.output.stroke);
    smallNote(gs, CX + gridW / 2 + 16, rowY + 8, 'orange = negative (soft)', '#f97316');

    shapeEq(gs, CX, rowY + gridH / 2 + 36,
      `SiLU(x)  [${seqLen}, ${dModel}]`, COLORS.output.stroke);
    sampleNote(gs, CX, rowY + gridH / 2 + 36 + 30,
      'used in LLaMA, EfficientNet — smooth, non-monotonic', COLORS.output.stroke);

    steps.push(makeStep(stepId, 'Output', 'Output',
      `SiLU(x) [${seqLen}, ${dModel}]`,
      'Output has the same shape. SiLU is non-monotonic (slightly negative for small negative x), which can improve model expressiveness.',
      'step-output', COLORS.output.stroke, COLORS.output.fill,
      [`# SiLU/Swish: smooth, non-monotonic, modern LLMs default`]));
    y = rowY + gridH / 2 + 36 + 30 + 24 + SHAPE_GAP;
  }

  return { steps, y };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Main renderer
// ═══════════════════════════════════════════════════════════════════════════════

export function renderActivationFunctionsDetailed(
  g: Gsel,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const seqLen = Number(params.seq_len) || 128;
  const dModel = Number(params.d_model) || 512;
  const variant = String(params.variant || 'all') as AFVariant;

  const stepsMeta: AFStep[] = [];
  let y = 10;

  lbl(g, CX, y + 14, 'Activation Functions', { size: 18, weight: '700', color: 'var(--text)' });
  y += 36;
  const variantLabel = variant === 'relu' ? 'ReLU' : variant === 'gelu' ? 'GELU' : variant === 'silu' ? 'SiLU / Swish' : 'All (comparison)';
  lbl(g, CX, y + 8,
    `${variantLabel} — nonlinear transformation of activations`,
    { size: 10, color: 'var(--text-muted)' });
  y += 30;

  y = paramSummary(g, CX, y, [
    `seq_len: ${seqLen}`, `d_model: ${dModel}`, `variant: ${variant.toUpperCase()}`,
  ]);
  y += 32;

  const { steps, y: finalY } = variant === 'relu'
    ? renderReLU(g, y, seqLen, dModel)
    : variant === 'gelu'
      ? renderGELU(g, y, seqLen, dModel)
      : variant === 'silu'
        ? renderSiLU(g, y, seqLen, dModel)
        : renderAll(g, y, seqLen, dModel);
  stepsMeta.push(...steps);
  y = finalY;

  // ── Footer ─────────────────────────────────────────────────────────────────
  y += 32;
  const insightText = variant === 'relu'
    ? 'ReLU (Rectified Linear Unit) is the simplest activation: max(0, x). It creates sparse activations (many zeros) which is computationally efficient. However, it suffers from the "dying ReLU" problem where neurons can permanently output zero. Used extensively in CNNs and older architectures.'
    : variant === 'gelu'
      ? 'GELU (Gaussian Error Linear Unit) smoothly gates activations using the Gaussian CDF. Unlike ReLU, it never fully zeros negative values — instead it softly attenuates them. This provides smooth gradients everywhere, avoiding the dying neuron problem. Used in BERT, GPT, and Vision Transformers.'
      : variant === 'silu'
        ? 'SiLU (Sigmoid Linear Unit), also known as Swish (when β=1), computes x·σ(x). It is smooth, non-monotonic (slightly negative for small negative inputs), and has been shown to outperform ReLU and GELU in many settings. Used in LLaMA, EfficientNet, and modern LLMs.'
        : 'Activation functions introduce non-linearity into neural networks. ReLU is fast and sparse but has dying neurons. GELU provides smooth gradients and is used in transformers. SiLU/Swish is non-monotonic and used in modern LLMs like LLaMA. The choice depends on the model architecture and training stability requirements.';

  y = drawExplanation(g as Sel, CX - (W - 160) / 2, y, W - 160, insightText, 'insight');
  y += 24;

  const perfText = `Input shape [${seqLen}, ${dModel}]. No learned parameters (${(seqLen * dModel).toLocaleString()} elements per forward pass). All activations are element-wise O(n).`;
  y = drawExplanation(g as Sel, CX - (W - 160) / 2, y, W - 160, perfText, 'perf');
  y += 24;

  drawComponentLink(g as Sel, CX - (W - 160) / 2, y, (W - 160) / 2 - 8, 56, 'dropout', 'Dropout');
  drawComponentLink(g as Sel, CX + 8, y, (W - 160) / 2 - 8, 56, 'cross-entropy', 'Cross Entropy');
  y += 80;

  const codeText = variant === 'relu'
    ? `# ReLU — fast, sparse\ndef relu(x):\n    return torch.clamp(x, min=0)`
    : variant === 'gelu'
      ? `# GELU — smooth, used in transformers\ndef gelu(x):\n    return x * 0.5 * (1 + torch.tanh(\n        math.sqrt(2/math.pi) * (x + 0.044715 * x**3)))`
      : variant === 'silu'
        ? `# SiLU / Swish — smooth, non-monotonic\ndef silu(x):\n    return x * torch.sigmoid(x)`
        : `# Activation functions comparison\nimport torch.nn.functional as F\nrelu_out = torch.relu(x)     # max(0, x)\ngelu_out = F.gelu(x)         # x * Phi(x)\nsilu_out = F.silu(x)         # x * sigmoid(x)`;

  y = drawCodeAnnotation(g as Sel, CX - (W - 160) / 2, y, W - 160,
    `Activation Functions — ${variantLabel} (Python)`,
    [`${variantLabel} — x[${seqLen},${dModel}] → out[${seqLen},${dModel}]`],
    codeText.split('\n'));
  y += 32;

  return { width: W, height: y, steps: stepsMeta };
}
